def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    if not b_intervals:
        return a_intervals

    # Merge overlapping/touching intervals in b for easier subtraction
    merged_b = []
    for start, end in b_intervals:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    result = []

    for a_start, a_end in a_intervals:
        current_start = a_start

        for b_start, b_end in merged_b:
            # No overlap with this b interval
            if b_end <= current_start or b_start >= a_end:
                continue

            # Add the part before this b interval
            if current_start < b_start:
                result.append([current_start, b_start])

            # Move past this b interval
            current_start = max(current_start, b_end)

            if current_start >= a_end:
                break

        # Add any remaining part after all b intervals
        if current_start < a_end:
            result.append([current_start, a_end])

    return result

